#!/usr/bin/env python3
"""Check local Markdown links in a docs folder. Stdlib only."""
import re
import sys
import urllib.parse
from pathlib import Path

LINK_RE = re.compile(r"\[[^\]]*\]\(([^)\s]+)(?:\s+\"[^\"]*\")?\)")


def check_file(path: Path, broken: list) -> None:
    in_fence = False
    for lineno, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if line.lstrip().startswith("```"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        for m in LINK_RE.finditer(line):
            target = m.group(1)
            if target.startswith("#"):
                continue  # in-page anchor
            if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", target):
                continue  # external (http:, mailto:, ...)
            rel = urllib.parse.unquote(target.split("#", 1)[0])
            if not rel:
                continue
            if not (path.parent / rel).exists():
                broken.append(f"{path}:{lineno}: {target}")


def main() -> int:
    root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("docs")
    if not root.is_dir():
        print(f"error: {root} is not a directory", file=sys.stderr)
        return 2
    broken = []
    for md in sorted(root.rglob("*.md")):
        check_file(md, broken)
    for line in broken:
        print(line)
    return 1 if broken else 0


if __name__ == "__main__":
    sys.exit(main())
